exercises.solutionCode:
String greetUser(String name, {String? title}) {
  if (title != null) {
    return 'Hello, $title $name!';
  }
  return 'Hello, $name!';
}

void main() {
  print(greetUser('Alice'));
  print(greetUser('Smith', title: 'Dr.'));
}
